// Build a clean, HTML-escaped task payload from the Gmail trigger output.
const e = $input.first().json;

const escape = (s = '') =>
  String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const subject = (e.subject || e.Subject || '(no subject)').toString().slice(0, 120);
const from    = e.from   || e.From   || 'unknown';
const body    = (e.text  || e.snippet || '').toString().slice(0, 1500);

const urgent = /\b(urgent|asap|p0|outage)\b/i.test(subject) ? 3 : 2;

const description =
  `<p><b>From:</b> ${escape(from)}</p>` +
  `<p><b>Subject:</b> ${escape(subject)}</p>` +
  `<p>${escape(body).replace(/\n/g, '<br>')}</p>`;

return [{
  json: {
    project_id: $env.FREEDCAMP_PROJECT_ID || 'REPLACE_WITH_PROJECT_ID',
    title: subject,
    description,
    priority: urgent,
    status: 0
  }
}];

// Surface the created task id (or the JSON-RPC error) in a flat shape.
const r = $input.first().json || {};

if (r.error) {
  throw new Error(`Freedcamp MCP error ${r.error.code}: ${r.error.message}`);
}

// MCP tool responses arrive as { result: { content: [{ type: 'text', text: '<json>' }] } }
let payload = r.result;
const text = r?.result?.content?.[0]?.text;
if (typeof text === 'string') {
  try { payload = JSON.parse(text); } catch { payload = { raw: text }; }
}

return [{ json: { ok: true, task: payload } }];
